const nowMs = Date.now();
const windowMs = 2 * 60 * 60 * 1000;
const payload = $input.first().json || {};
const rows = Array.isArray(payload.deployments) ? payload.deployments : [];
const recent = rows.filter(d => { const t = Date.parse(d.deployed_at || ''); const age = nowMs - t; return !isNaN(t) && age >= 0 && age <= windowMs; }).map(d => ({ repo: d.repo || ($env.PETER_GITHUB_REPO || 'unknown/repo'), sha: d.sha, deployed_at: d.deployed_at, service: d.service || 'unknown' }));
return [{ json: { recent_deploys: recent } }];

const merged = Object.assign({}, ...$input.all().map(i => i.json));
const signal = $('Normalize Signal').first().json;
const context = {
  maintenance_window: merged.maintenance_window === true,
  recent_deploys: Array.isArray(merged.recent_deploys) ? merged.recent_deploys : [],
  complaint_count: Number(merged.complaint_count) || 0,
  complaint_samples: (Array.isArray(merged.complaint_samples) ? merged.complaint_samples : []).slice(0, 5)
};
const infoOnly = (signal.severity_hint || '') === 'info';
const known_noise = context.maintenance_window || (context.recent_deploys.length > 0 && infoOnly);
const noise_reason = context.maintenance_window ? 'maintenance_window' : (known_noise ? 'info_alert_inside_deploy_window' : '');
return [{ json: { context, known_noise, noise_reason } }];

const signal = $('Normalize Signal').first().json;
const decision = $json;
console.log('PETER suppression', JSON.stringify({ signal_id: signal.id, reason: decision.noise_reason }));
return [{ json: { status: 'suppressed', signal_id: signal.id, reason: decision.noise_reason, context: decision.context } }];

